import{_ as o,o as t,c as d,a0 as a}from"./chunks/framework.DYS8d9tm.js";const m=JSON.parse('{"title":"🚀 WealthFam Product Backlog","description":"","frontmatter":{},"headers":[],"relativePath":"Management/backlog.md","filePath":"Management/backlog.md"}'),c={name:"Management/backlog.md"};function i(n,e,r,s,l,u){return t(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="🚀-wealthfam-product-backlog" tabindex="-1">🚀 WealthFam Product Backlog <a class="header-anchor" href="#🚀-wealthfam-product-backlog" aria-label="Permalink to &quot;🚀 WealthFam Product Backlog&quot;">​</a></h1><p><em>Tracks active bugs, tech debt, upcoming enhancements, and deferred work across <code>Backend</code>, <code>Parser</code>, <code>Web-App</code>, and <code>Mobile-App</code>. Per <a href="./PRACTICES.html">PRACTICES.md</a>, resolved items are archived in <a href="./CHANGELOG.html">CHANGELOG.md</a>.</em></p><blockquote><p><strong>How to use this backlog:</strong> Related items are grouped into <strong>Parent Tasks (Epics)</strong> with <strong>Child Tasks</strong> so overlapping files and invariants are fixed together in one branch/PR. Use the <strong>Execution &amp; Mutual Exclusivity Matrix</strong> below to pick parallelizable work safely.</p></blockquote><hr><h2 id="🗺️-execution-order-mutual-exclusivity-matrix" tabindex="-1">🗺️ Execution Order &amp; Mutual Exclusivity Matrix <a class="header-anchor" href="#🗺️-execution-order-mutual-exclusivity-matrix" aria-label="Permalink to &quot;🗺️ Execution Order &amp; Mutual Exclusivity Matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Parent Task</th><th>Priority</th><th>Platforms</th><th>Depends On</th><th>Mutually Exclusive (Safe in Parallel With)</th></tr></thead><tbody><tr><td><strong>P1-E</strong></td><td>Net Worth, Analytics, Budgets &amp; Recurring Parity</td><td>🔴 P1</td><td>Backend, Web, Mobile</td><td>None</td><td>P2-B, P2-C</td></tr><tr><td><strong>P2-A</strong></td><td>Web-App Data/Timezone, Filter &amp; Account View Fixes</td><td>🟠 P2</td><td>Web</td><td>None</td><td>P1-B, P2-B, P2-C</td></tr><tr><td><strong>P2-B</strong></td><td>Mobile Gateway Deduplication &amp; API Route Normalization</td><td>🟠 P2</td><td>Backend (Mobile), Mobile</td><td>None</td><td>P1-B, P1-D <em>(P2-B.1 only)</em>, P1-E, P2-A, P2-C</td></tr><tr><td><strong>P2-C</strong></td><td>Ops &amp; Data Hygiene (14-Day Log Auto-Prune)</td><td>🟠 P2</td><td>Backend, Web</td><td>None</td><td>Everything else</td></tr><tr><td><strong>P3</strong></td><td>Long-Term Roadmap (MCP, WealthFam Score, Multi-Currency FX)</td><td>🟣 P3</td><td>Full Stack</td><td>P1-E <em>(for P3-2, P3-3; P3-1 is independent)</em></td><td>—</td></tr></tbody></table><hr><h2 id="🔴-p1-—-high-priority-core-financial-accuracy-ingestion-client-parity" tabindex="-1">🔴 P1 — High Priority (Core Financial Accuracy, Ingestion &amp; Client Parity) <a class="header-anchor" href="#🔴-p1-—-high-priority-core-financial-accuracy-ingestion-client-parity" aria-label="Permalink to &quot;🔴 P1 — High Priority (Core Financial Accuracy, Ingestion &amp; Client Parity)&quot;">​</a></h2><h3 id="p1-e-net-worth-analytics-budgets-recurring-parity" tabindex="-1">P1-E: Net Worth, Analytics, Budgets &amp; Recurring Parity <a class="header-anchor" href="#p1-e-net-worth-analytics-budgets-recurring-parity" aria-label="Permalink to &quot;P1-E: Net Worth, Analytics, Budgets &amp; Recurring Parity&quot;">​</a></h3><p><em>Depends on <code>P1-D.2</code> (<code>FixedDepositService.valuation()</code>) for Child <code>P1-E.1</code>; mutually exclusive from P1-B/C.</em></p><ul><li>[ ] <strong>[P1-E.1] Net Worth, History Timeline &amp; Goal Asset Parity</strong> <code>[Backend]</code> <code>[Web]</code>: <ul><li>Backend (<code>analytics/core.py</code>, <code>analytics/history.py</code>, <code>analytics/investments.py</code>, <code>investment_goal_service.py</code>): include <code>MutualFundHolding</code>, accrued FD/RD (<code>FixedDepositService.valuation()</code>), and PF consistently across <code>CoreAnalytics</code>, <code>HistoryAnalytics</code>, and <code>InvestmentAnalytics.get_family_wealth</code>; replay same-day post-snapshot transactions in <code>HistoryAnalytics</code>; block <code>CREDIT_CARD</code>/<code>LOAN</code> liability accounts as goal assets (<code>ValueError</code> → <code>400</code>).</li><li>Web-App: exclude <code>CREDIT_CARD</code>/<code>LOAN</code> in <code>InvestmentGoals.vue</code> / <code>LinkAssetModal.vue</code>; fix <code>Dashboard.vue</code> (<code>:92, 349-355</code> <code>% MoM</code> computing 1-day delta &amp; dividing by un-abs&#39;d negative net worth, and <code>:192-195</code> hardcoding green/gains when <code>mfPortfolio.pl &lt; 0</code>).</li></ul></li><li>[ ] <strong>[P1-E.2] Uncategorized Spending, Soft-Deleted Accounts &amp; Role Filter Parity</strong> <code>[Backend]</code>: <ul><li>Use consistent <code>outerjoin</code> on <code>Category</code> across <code>CoreAnalytics</code>, <code>SpendingAnalytics</code>, <code>HistoryAnalytics</code> (<code>get_budget_history:148</code>, <code>get_calendar_heatmap:269</code>), and <code>BudgetService</code> so uncategorized transactions match across Dashboard, Insights, and Budgets.</li><li>Always filter <code>Account.is_deleted == False</code> in Family/All analytics views and <code>Backend/app/modules/mobile/services/expense_group_service.py</code> (also change mobile <code>delete_expense_group</code> from hard-delete to soft-delete).</li><li>Fix <code>CHILD</code> role filters in <code>CoreAnalytics</code> and <code>TransactionService</code> (<code>&quot;CREDIT_CARD&quot;, &quot;LOAN&quot;</code> instead of <code>&quot;CREDIT&quot;</code>).</li></ul></li><li>[ ] <strong>[P1-E.3] Recurring Transactions Sign, Edit &amp; Forecast Window</strong> <code>[Backend]</code> <code>[Web]</code> <code>[Mobile]</code>: <ul><li>Backend (<code>recurring_service.py</code>, <code>analytics/core.py</code>): standardize <code>RecurringTransaction.amount</code> as positive magnitude (<code>abs(Decimal)</code>) on create/update, pass signed amount based on <code>item.type</code> (<code>DEBIT</code>/<code>CREDIT</code>), and project all occurrences within the forecast window on liquid accounts.</li><li>Web-App (<code>RecurringTab.vue</code>): add <code>type</code> selector, preserve <code>rec.type</code> and <code>next_run_date</code> on edit, and call <code>resetForm()</code> on &quot;Add Subscription&quot; so it doesn&#39;t overwrite the previously edited subscription.</li><li>Mobile-App (<code>analytics_recurring_tab.dart:831-835</code>): remove hardcoded <code>&#39;type&#39;: &#39;DEBIT&#39;</code> &amp; <code>-amt.abs()</code>; add <code>DEBIT</code>/<code>CREDIT</code> selector so editing recurring income doesn&#39;t convert it to a debit.</li></ul></li></ul><hr><h2 id="🟠-p2-—-medium-priority-client-polish-mobile-gateway-ops-hygiene" tabindex="-1">🟠 P2 — Medium Priority (Client Polish, Mobile Gateway &amp; Ops Hygiene) <a class="header-anchor" href="#🟠-p2-—-medium-priority-client-polish-mobile-gateway-ops-hygiene" aria-label="Permalink to &quot;🟠 P2 — Medium Priority (Client Polish, Mobile Gateway &amp; Ops Hygiene)&quot;">​</a></h2><h3 id="p2-a-web-app-timestamp-filter-account-view-bugs" tabindex="-1">P2-A: Web-App Timestamp, Filter &amp; Account View Bugs <a class="header-anchor" href="#p2-a-web-app-timestamp-filter-account-view-bugs" aria-label="Permalink to &quot;P2-A: Web-App Timestamp, Filter &amp; Account View Bugs&quot;">​</a></h3><p><em>Web-only (mutually exclusive from P1-B, P2-B, and P2-C); overlaps Web views (<code>CreditCards.vue</code>, <code>AccountDetails.vue</code>, <code>Deposits.vue</code>, <code>Dashboard.vue</code>) with P1-A/C/D/E.</em></p><ul><li>[ ] <strong>[P2-A.1] Transaction Edit Shifts Timestamp Backward by Local UTC Offset</strong> <code>[Web]</code>: <code>useTransactionModals.ts:127, 172</code> slices UTC ISO strings (<code>txn.date.slice(0, 16)</code>) into local wall time and re-converts via <code>toISOString()</code>, subtracting local offset (e.g. <code>-5h30m</code> in IST) on every save. <em>Fix</em>: Convert UTC → local wall time when populating the picker before converting back to UTC on submit.</li><li>[ ] <strong>[P2-A.2] &quot;Today&quot; Filter Includes Tomorrow &amp; Family Member Filter Leaks</strong> <code>[Web]</code>: <ul><li>Fix <code>useTransactionState.ts:149</code> (<code>case &#39;today&#39;</code> setting <code>end = today + 1</code> while backend <code>end_date</code> is inclusive).</li><li>Propagate <code>auth.selectedMemberId</code> and watch changes in <code>stores/finance.ts:32</code> (<code>fetchAll</code>), <code>CreditCards.vue:881</code>, <code>Deposits.vue:597</code>, <code>ProvidentFunds.vue:619</code>, and <code>Dashboard.vue:428</code> (<code>getRecurringTransactions</code>).</li></ul></li><li>[ ] <strong>[P2-A.3] <code>AccountDetails.vue</code> Blank Initial Chart, Un-Debounced Search &amp; Unverified Account Lookup</strong> <code>[Web]</code>: Default <code>periodFilter</code> to <code>&#39;month&#39;</code> for non-CC accounts (instead of <code>&#39;current&#39;</code>), debounce search and remove duplicate <code>@input=&quot;fetchTransactions&quot;</code> (which also passes DOM <code>InputEvent</code> as <code>options</code>, setting <code>page</code>/<code>limit</code> to <code>undefined</code>, and fires 4 requests/keystroke alongside <code>watch</code>), and pass <code>includeUnverified: true</code> in <code>fetchAccount()</code>.</li></ul><h3 id="p2-b-mobile-gateway-deduplication-api-route-normalization" tabindex="-1">P2-B: Mobile Gateway Deduplication &amp; API Route Normalization <a class="header-anchor" href="#p2-b-mobile-gateway-deduplication-api-route-normalization" aria-label="Permalink to &quot;P2-B: Mobile Gateway Deduplication &amp; API Route Normalization&quot;">​</a></h3><p><em><code>P2-B.1</code> is mutually exclusive from P1-A/B/D/E and P2-A/C; <code>P2-B.2</code> overlaps with P1-A.3, P1-C.2, and P1-D.1 on Mobile repositories/services.</em></p><ul><li>[ ] <strong>[P2-B.1] Deduplicate 4 Shadowed Routes in Mobile Gateway &amp; Fix Funds Member Filter</strong> <code>[Backend]</code> <code>[Mobile]</code>: <code>Backend/app/modules/mobile/api/router.py</code> registers duplicate handlers for <code>GET /funds</code> (<code>1419</code> vs <code>2671</code>), <code>GET /funds/{scheme_code}</code> (<code>1560</code> vs <code>2679</code>), <code>GET /categories</code> (<code>1671</code> vs <code>2610</code>), and <code>GET /vendor/stats</code> (<code>849</code> vs <code>2847</code>). Because <code>GET /funds</code> at <code>1419</code> expects <code>member_id</code> while <code>Mobile-App/funds_repository.dart:36-39</code> sends <code>user_id</code>, family member filtering on Mutual Funds is silently ignored. <em>Fix</em>: Remove shadowed duplicates (preserving <code>#L1419</code>&#39;s <code>MobileFundsResponse</code> shape with both <code>user_id</code> &amp; <code>member_id</code> query aliases for APK compatibility, and verifying <code>GET /categories</code> schema compatibility before dropping either handler).</li><li>[~] <strong>[P2-B.2] Mobile API Strictness &amp; Route Normalization</strong> <em>(In Progress / Deferred)</em> <code>[Mobile]</code> <code>[Backend]</code>: Migrate remaining direct <code>/api/v1/finance/*</code> and <code>/api/v1/ingestion/triage/*</code> calls across <code>Mobile-App</code> repositories/services (<code>accounts</code>, <code>categories</code>, <code>finance</code>, <code>funds</code>, <code>loans</code>, <code>statements</code>, <code>vault</code>) to dedicated <code>/api/v1/mobile/*</code> endpoints. <em>Explicitly exempt</em> shared cross-client endpoints: <code>/api/v1/ingestion/sms</code> (canonical per <code>sms_flow.md</code>), <code>/api/v1/auth/*</code>, <code>/api/v1/brands/*</code>, and <code>/api/v1/telemetry/*</code> (document exemption in <code>PRACTICES.md</code> §2).</li></ul><h3 id="p2-c-ops-data-hygiene" tabindex="-1">P2-C: Ops &amp; Data Hygiene <a class="header-anchor" href="#p2-c-ops-data-hygiene" aria-label="Permalink to &quot;P2-C: Ops &amp; Data Hygiene&quot;">​</a></h3><ul><li>[ ] <strong>[P2-C.1] 14-Day Auto-Prune for Ingestion &amp; Sync Logs</strong> <code>[Backend]</code> <code>[Web]</code>: Add a scheduled background job in <code>scheduler.py</code> (configurable via <code>INGESTION_LOG_RETENTION_DAYS = 14</code> in <code>config.py</code>) to prune <code>email_sync_item_logs</code> <em>before</em> <code>email_sync_logs</code> (no <code>ondelete=&quot;CASCADE&quot;</code> FK) and <code>ingestion_events</code> older than 14 days, and cap <code>Web-App/src/views/settings/IngestionsSettings.vue</code> date filters to a maximum 14-day review window with a subtle retention notice.</li></ul><hr><h2 id="🟣-p3-—-long-term-roadmap-future-capabilities" tabindex="-1">🟣 P3 — Long-Term Roadmap &amp; Future Capabilities <a class="header-anchor" href="#🟣-p3-—-long-term-roadmap-future-capabilities" aria-label="Permalink to &quot;🟣 P3 — Long-Term Roadmap &amp; Future Capabilities&quot;">​</a></h2><h3 id="🛠️-new-infrastructure-tooling" tabindex="-1">🛠️ New Infrastructure &amp; Tooling <a class="header-anchor" href="#🛠️-new-infrastructure-tooling" aria-label="Permalink to &quot;🛠️ New Infrastructure &amp; Tooling&quot;">​</a></h3><ul><li>[ ] <strong>[P3-1] MCP Server (FastAPI Module)</strong>: Implement a Model Context Protocol (MCP) server leveraging FastAPI as a distinct, decoupled integration module.</li></ul><h3 id="💎-advanced-fintech-features" tabindex="-1">💎 Advanced Fintech Features <a class="header-anchor" href="#💎-advanced-fintech-features" aria-label="Permalink to &quot;💎 Advanced Fintech Features&quot;">​</a></h3><ul><li>[ ] <strong>[P3-2] Financial Health Score</strong>: Create a proprietary &quot;WealthFam Score&quot; based on savings rate, emergency runway months, and debt-to-income ratios.</li><li>[ ] <strong>[P3-3] Multi-Currency FX Normalization</strong>: Convert non-base-currency accounts (<code>Account.currency != base_currency</code>) using FX rates before summing into Net Worth, History, and Family Wealth analytics instead of adding raw balances across currencies.</li></ul>',27)])])}const g=o(c,[["render",i]]);export{m as __pageData,g as default};
